/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import fs from 'node:fs'
import { createRequire } from 'node:module'
import ts from 'typescript'

const source = fs.readFileSync('app/ContactForm.tsx', 'utf8')
const compiled = ts.transpileModule(source, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX },
}).outputText
const componentModule = { exports: {} }
new Function('require', 'module', 'exports', compiled)(
  createRequire(import.meta.url), componentModule, componentModule.exports,
)
const tree = componentModule.exports.default()
const form = tree.props.children.find(child => child.type === 'form')
assert.equal(typeof form.props.action, 'function')
const valid = { name: ' Alex ', email: ' alex@example.com ', message: ' Hello"'! '"' }
const data = () => {
  const formData = new FormData()
  for (const [key, value] of Object.entries(valid)) formData.set(key, value)
  return formData
}
for (const field of Object.keys(valid)) {
  for (const value of [undefined, '', ' \\n\\t ', new Blob(['text'])]) {
    const formData = data()
    if (value === undefined) formData.delete(field)
    else formData.set(field, value)
    await assert.rejects(form.props.action(formData), /Name, email, and message are required/)
  }
}
const logged = []
const originalLog = console.log
try {
  console.log = (...args) => logged.push(args)
  await form.props.action(data())
} finally {
  console.log = originalLog
}
assert.deepEqual(logged, [['Saving contact message:', {
  name: 'Alex', email: 'alex@example.com', message: 'Hello"'!'"',
}]])
console.log('Passed: valid submission and 12 invalid-field cases.')
NODE"
